-- RAQUET_BATCH_STATS (Snowflake JavaScript UDTF)
-- Processes multiple raster tiles in a single JavaScript context, eliminating
-- per-row JS initialization overhead.
--
-- Instead of calling ST_RASTERSUMMARYSTATS once per tile (N JS invocations),
-- this UDTF processes all tiles in one invocation: metadata is parsed once,
-- libraries are loaded once, and the JS engine stays warm across all rows.
--
-- Parameters (per input row):
--   BLK: DOUBLE - The QUADBIN block identifier (cast from NUMBER)
--   BAND: BINARY - The compressed band data
--   META: VARCHAR - JSON metadata (parsed once, reused for all rows)
--   BAND_IDX: DOUBLE - The band index (0-based)
--
-- Returns TABLE:
--   BLOCK_ID: DOUBLE - The QUADBIN block identifier
--   CNT: DOUBLE - Count of valid (non-nodata) pixels
--   SM: DOUBLE - Sum of valid pixel values
--   MN: DOUBLE - Minimum valid pixel value
--   MX: DOUBLE - Maximum valid pixel value
--   AVG_VAL: DOUBLE - Mean of valid pixel values
--   STD: DOUBLE - Standard deviation
--
-- Usage:
--   WITH metadata AS (
--       SELECT metadata FROM RAQUET_DB.RAQUET.SLOPE_15GB WHERE block = 0 LIMIT 1
--   ),
--   site_blocks AS (
--       SELECT f.VALUE::NUMBER AS block_id
--       FROM TABLE(FLATTEN(RAQUET_DB.RAQUET.__RAQUET_REGION_BLOCKS(
--           ST_GEOGRAPHYFROMWKT('POLYGON((...))'), 17, 17, 'intersects'
--       ))) f
--   ),
--   batch AS (
--       SELECT r.block::DOUBLE AS blk, r.band_1, m.metadata, 0::DOUBLE AS bidx
--       FROM RAQUET_DB.RAQUET.SLOPE_15GB r
--       JOIN site_blocks sb ON r.block = sb.block_id
--       CROSS JOIN metadata m
--       WHERE r.block != 0
--   )
--   SELECT
--       SUM(s.CNT)::INT as total_pixels,
--       ROUND(SUM(s.SM) / NULLIF(SUM(s.CNT), 0), 4) as mean_slope,
--       MIN(s.MN) as min_slope,
--       MAX(s.MX) as max_slope,
--       COUNT(*) as num_tiles
--   FROM batch b,
--   TABLE(RAQUET_DB.RAQUET.RAQUET_BATCH_STATS(
--       b.blk, b.band_1, b.metadata, b.bidx
--   ) OVER (PARTITION BY 1)) s;

CREATE OR REPLACE FUNCTION RAQUET_DB.RAQUET.RAQUET_BATCH_STATS(
    BLK DOUBLE,
    BAND BINARY,
    META VARCHAR,
    BAND_IDX DOUBLE
)
RETURNS TABLE(BLOCK_ID DOUBLE, CNT DOUBLE, SM DOUBLE, MN DOUBLE, MX DOUBLE, AVG_VAL DOUBLE, STD DOUBLE)
LANGUAGE JAVASCRIPT
