        this.pixelCount = 0;
        this.nodata = null;
        this.isGzip = false;
        this.bandIdx = 0;
    },

    processRow: function(row, rowWriter, context) {
        // Parse metadata once on first non-null metadata row
        if (!this.meta && row.META) {
            this.meta = JSON.parse(row.META);
            this.bandIdx = Number(row.BAND_IDX) || 0;
            this.bandInfo = this.meta.bands[this.bandIdx];
            var tiling = this.meta.tiling || {};
            var blockWidth = Number(tiling.block_width) || 256;
            var blockHeight = Number(tiling.block_height) || 256;
            this.pixelCount = blockWidth * blockHeight;
            this.nodata = this.bandInfo.nodata;
            this.isGzip = this.meta.compression === 'gzip';
        }

        // Skip if no band data
        if (!row.BAND || row.BLK === 0) {
            return;
        }

        var data = new Uint8Array(row.BAND);

        // Decompress gzip
        if (this.isGzip) {
            data = this.raquetInflateLib.inflate(data);
        }

        // Compute statistics
        var stats = this.raquetLib.computeBandStats(data, this.bandInfo.type, this.pixelCount, this.nodata);

        rowWriter.writeRow({
            BLOCK_ID: row.BLK,
            CNT: stats.count,
            SM: stats.sum,
            MN: stats.min,
            MX: stats.max,
            AVG_VAL: stats.mean,
            STD: stats.stddev
        });
    },

    finalize: function(rowWriter, context) {
        // Nothing to finalize
    }
}
$$;
